<script setup>
import {computed,onMounted,ref} from 'vue'
import {api} from './api'
import VariableInsert from './VariableInsert.vue'
import HttpBodyBuilder from './HttpBodyBuilder.vue'
const items=ref([]),fields=ref([]),contexts=ref([]),loading=ref(false),error=ref(''),editing=ref(null),testResult=ref(null),testing=ref(false),search=ref(''),status=ref('all'),testContextKey=ref('')
const creatingField=ref(false),fieldSaving=ref(false),fieldError=ref(''),mappingForField=ref(null),newField=ref({label:'',key:'',field_type:'text'})
const blank=()=>({name:'',description:'',method:'POST',endpoint_url:'',headers:[],query:[],cookies:[],body_type:'json',body:{},response_mappings:[],timeout_seconds:15,active:true})
const filtered=computed(()=>items.value.filter(x=>(status.value==='all'||(status.value==='active'?x.active:!x.active))&&(!search.value||x.name.toLowerCase().includes(search.value.toLowerCase())||x.endpoint_url.toLowerCase().includes(search.value.toLowerCase()))))
const responsePaths=computed(()=>testResult.value?.response_paths||[])
const selectedContext=computed(()=>contexts.value.find(x=>`${x.channel}:${x.conversation_id}`===testContextKey.value)||null)
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{day:'numeric',month:'short',year:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'—'}
async function load(){loading.value=true;error.value='';try{items.value=await api.httpApis()}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadFields(){try{fields.value=await api.contactFields()}catch{fields.value=[]}}
async function loadContexts(){try{contexts.value=await api.httpApiTestContexts();if(!testContextKey.value&&contexts.value.length)testContextKey.value=`${contexts.value[0].channel}:${contexts.value[0].conversation_id}`}catch{contexts.value=[]}}
function addRow(key){editing.value[key].push({key:'',value:''})} function removeRow(key,i){editing.value[key].splice(i,1)}
function addMapping(source_path=''){editing.value.response_mappings.push({source_path,target_key:''})} function removeMapping(i){editing.value.response_mappings.splice(i,1)} function mapWholeResponse(){addMapping('$')}
function insertRowVariable(row,token){row.value=String(row.value||'')+token} function insertEndpointVariable(token){editing.value.endpoint_url=String(editing.value.endpoint_url||'')+token}
function rawBodyText(){return typeof editing.value?.body==='string'?editing.value.body:JSON.stringify(editing.value?.body??{},null,2)} function setRawBody(v){editing.value.body=v} function insertRawVariable(token){editing.value.body=rawBodyText()+token}
function normalizeBody(){if(['json','form'].includes(editing.value.body_type)&&(!editing.value.body||typeof editing.value.body!=='object'||Array.isArray(editing.value.body))){try{const p=JSON.parse(editing.value.body||'{}');editing.value.body=p&&typeof p==='object'&&!Array.isArray(p)?p:{}}catch{editing.value.body={}}}if(editing.value.body_type==='none')editing.value.body=null;if(editing.value.body_type==='raw'&&typeof editing.value.body!=='string')editing.value.body=JSON.stringify(editing.value.body??{},null,2)}
function create(){editing.value=blank();testResult.value=null} function edit(x){editing.value=JSON.parse(JSON.stringify(x));editing.value.response_mappings=editing.value.response_mappings||[];testResult.value=null}
async function save(){error.value='';try{const saved=editing.value.id?await api.updateHttpApi(editing.value.id,editing.value):await api.createHttpApi(editing.value);editing.value=saved;await load();return saved}catch(e){error.value=e.message;return null}}
async function test(){testing.value=true;testResult.value=null;try{const saved=await save();if(!saved?.id){testResult.value={success:false,error:error.value||'Unable to save API before testing'};return}const c=selectedContext.value;testResult.value=await api.testHttpApi(saved.id,c?{channel:c.channel,conversation_id:c.conversation_id}:{});await load()}catch(e){testResult.value={success:false,error:e.message}}finally{testing.value=false}}
async function remove(x){if(!confirm(`Delete “${x.name}”?`))return;await api.deleteHttpApi(x.id);await load()}
function slugKey(v){return String(v||'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').replace(/^[^a-z]+/,'')}
function openFieldCreator(m=null){mappingForField.value=m;fieldError.value='';newField.value={label:'',key:'',field_type:'text'};creatingField.value=true} function fieldLabelChanged(){if(!newField.value.key)newField.value.key=slugKey(newField.value.label)} function closeFieldCreator(){creatingField.value=false;mappingForField.value=null;fieldError.value=''}
async function createMappingField(){fieldError.value='';const label=String(newField.value.label||'').trim(),key=slugKey(newField.value.key);if(!label||!key){fieldError.value='Field name and key are required.';return}fieldSaving.value=true;try{const created=await api.createContactField({label,key,field_type:newField.value.field_type||'text',required:false,active:true,sort_order:100,options:[]});await loadFields();if(mappingForField.value)mappingForField.value.target_key=created?.key||key;closeFieldCreator()}catch(e){fieldError.value=e.message}finally{fieldSaving.value=false}}
onMounted(()=>{load();loadFields();loadContexts()})
</script>
<template><section class="http-page"><header><div><p class="eyebrow">Integrations</p><h1>HTTP APIs</h1><p>Connect and manage reusable outbound HTTP APIs for flows and automations.</p></div><button class="primary" @click="create">＋ Create API</button></header><div v-if="error" class="error">{{error}}</div>
<template v-if="!editing"><div class="toolbar"><select v-model="status"><option value="all">Any status</option><option value="active">Active</option><option value="inactive">Inactive</option></select><input v-model="search" placeholder="Search APIs…"><button @click="load">↻ Refresh</button></div><div class="card"><div v-if="loading" class="empty">Loading…</div><div v-else-if="!filtered.length" class="empty">No HTTP APIs yet. Create your first reusable integration.</div><table v-else><thead><tr><th>API name</th><th>Method</th><th>Verified</th><th>Total calls</th><th>Success</th><th>Error</th><th>Last called</th><th>Actions</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td><strong>{{x.name}}</strong><small>{{x.endpoint_url}}</small></td><td><span class="method">{{x.method}}</span></td><td><span :class="['verified',x.verified?'yes':'no']">{{x.verified?'✓ Verified':'Not verified'}}</span></td><td>{{x.total_calls}}</td><td>{{x.total_success}}</td><td>{{x.total_error}}</td><td>{{fmt(x.last_called_at)}}</td><td><button @click="edit(x)">✎</button><button class="danger" @click="remove(x)">×</button></td></tr></tbody></table></div></template>
<template v-else><button class="back" @click="editing=null">← Back to HTTP APIs</button><div class="editor-grid"><main>
<section class="card form-card"><h2>API Details</h2><p>Enter the basic connection information for the API.</p><div class="details"><label>API Name<input v-model="editing.name"></label><label>Method<select v-model="editing.method"><option v-for="m in ['GET','POST','PUT','PATCH','DELETE']" :key="m">{{m}}</option></select></label><label class="url">Endpoint URL<input v-model="editing.endpoint_url" placeholder="https://api.example.com/v1/resource"><VariableInsert :fields="fields" @insert="insertEndpointVariable"/></label></div></section>
<section class="card form-card"><h2>Request Data</h2><p>Configure headers, query parameters, cookies and request body.</p><div v-for="group in ['headers','query','cookies']" :key="group" class="pairs"><div class="pair-head"><strong>{{group.charAt(0).toUpperCase()+group.slice(1)}}</strong><button @click="addRow(group)">＋ Add</button></div><div v-for="(row,i) in editing[group]" :key="i" class="pair"><input v-model="row.key" placeholder="Key"><div class="value-with-variable"><input v-model="row.value" placeholder="Value / %variable%"><VariableInsert :fields="fields" @insert="token=>insertRowVariable(row,token)"/></div><button @click="removeRow(group,i)">×</button></div></div><div class="body"><label>Body Type<select v-model="editing.body_type" @change="normalizeBody"><option value="none">None</option><option value="json">JSON</option><option value="form">Form URL Encoded</option><option value="raw">Raw / Text</option></select></label><HttpBodyBuilder v-if="['json','form'].includes(editing.body_type)" v-model="editing.body" :fields="fields" :body-type="editing.body_type"/><label v-else-if="editing.body_type==='raw'">Raw Body<textarea :value="rawBodyText()" @input="setRawBody($event.target.value)"></textarea><VariableInsert :fields="fields" @insert="insertRawVariable"/></label><div v-else class="no-body">This request will be sent without a body.</div></div></section>
<section class="card form-card"><div class="test-head"><div><h2>Test & Verify</h2><p>Choose a real subscriber to resolve variables exactly as a flow would.</p></div><button class="primary" :disabled="testing" @click="test">{{testing?'Sending…':'Send Test Request'}}</button></div><div class="test-context"><label>Test subscriber<select v-model="testContextKey"><option value="">No subscriber — send variables literally</option><option v-for="c in contexts" :key="`${c.channel}:${c.conversation_id}`" :value="`${c.channel}:${c.conversation_id}`">{{c.channel==='telegram'?'Telegram':'WhatsApp'}} · {{c.label}} · {{c.detail}}</option></select></label><div v-if="selectedContext" class="context-note"><strong>{{selectedContext.channel==='telegram'?'Telegram':'WhatsApp'}} runtime context</strong><span>Subscriber {{selectedContext.subscriber_id}} · conversation #{{selectedContext.conversation_id}}</span><span>Custom fields and latest %input.*% answers will be resolved for this subscriber.</span></div></div><div v-if="testResult" :class="['response',testResult.success?'ok':'bad']"><div class="response-meta"><span v-if="testResult.status_code"><strong>Status</strong> {{testResult.status_code}}</span><span v-if="testResult.method"><strong>Method</strong> {{testResult.method}}</span><span v-if="testResult.duration_ms!=null"><strong>Duration</strong> {{testResult.duration_ms}} ms</span></div><div v-if="testResult.requested_url"><strong>Requested</strong> {{testResult.requested_url}}</div><div v-if="testResult.final_url"><strong>Final URL</strong> {{testResult.final_url}}</div><div v-if="testResult.error" class="response-error">{{testResult.error}}</div><pre>{{testResult.response_json?JSON.stringify(testResult.response_json,null,2):(testResult.response||'')}}</pre></div><div v-else class="response">Response will appear here after test…</div></section></main>
<aside><section class="card form-card"><h2>Automation</h2><p>This saved API becomes selectable from any WhatsApp or Telegram HTTP Request flow block.</p><label>Timeout (seconds)<input v-model.number="editing.timeout_seconds" type="number" min="1" max="120"></label><label class="check"><input v-model="editing.active" type="checkbox"> Active</label><button class="save" @click="save">Save API</button></section><section class="card form-card mapping-card"><div class="mapping-head"><div><h2>Response Mapping</h2><p>Save values or the complete JSON response into contact custom fields.</p></div><div class="mapping-actions"><button @click="openFieldCreator()">＋ Custom Field</button><button @click="addMapping()">＋ Add</button></div></div><div v-if="testResult?.success" class="root-map"><strong>$ · Entire response</strong><button @click="mapWholeResponse">＋ Map entire response</button></div><div v-if="!editing.response_mappings.length" class="mapping-note">Run a successful JSON test, then map a response field.</div><div v-for="(m,i) in editing.response_mappings" :key="i" class="mapping-row"><label>Response field<input v-model="m.source_path" list="response-paths"></label><span>→</span><label>Custom field key<div class="field-target"><input v-model="m.target_key" list="field-keys"><button @click="openFieldCreator(m)">＋</button></div></label><button @click="removeMapping(i)">×</button></div><datalist id="response-paths"><option v-for="p in responsePaths" :key="p.path" :value="p.path">{{p.preview}}</option></datalist><datalist id="field-keys"><option v-for="f in fields" :key="f.id" :value="f.key">{{f.label}}</option></datalist><button v-if="editing.response_mappings.length" class="save" @click="save">Save Mappings</button></section></aside></div></template>
<div v-if="creatingField" class="field-modal-bg" @click.self="closeFieldCreator"><form class="field-modal" @submit.prevent="createMappingField"><div class="field-modal-head"><h2>Add Custom Field</h2><button type="button" @click="closeFieldCreator">×</button></div><div v-if="fieldError" class="error">{{fieldError}}</div><label>Field name<input v-model="newField.label" required @input="fieldLabelChanged"></label><label>Variable / key<input v-model="newField.key" required></label><label>Field type<select v-model="newField.field_type"><option value="text">Text / JSON</option><option value="textarea">Textarea</option><option value="email">Email</option><option value="number">Number</option><option value="date">Date</option><option value="checkbox">Checkbox</option></select></label><footer><button type="button" @click="closeFieldCreator">Cancel</button><button class="primary" :disabled="fieldSaving">{{fieldSaving?'Creating…':'Create Field'}}</button></footer></form></div></section></template>
<style scoped>
.http-page{margin-left:220px;padding:34px 38px;min-height:100vh;background:#f4f7f6;color:#17251e}.http-page>header,.test-head,.pair-head,.mapping-head,.field-modal-head{display:flex;justify-content:space-between;align-items:center}.http-page h1{font-size:30px;margin:2px 0 5px}.http-page h2{margin:0 0 6px;font-size:18px}.http-page p{color:#74867e}.eyebrow{text-transform:uppercase;color:#119052!important;font-size:11px;font-weight:800;letter-spacing:.08em;margin:0}.primary,.save{border:0;background:#168fd0;color:#fff;border-radius:9px;padding:11px 15px;font-weight:800;cursor:pointer}.save{background:#16a861;width:100%;margin-top:12px}button{cursor:pointer}.toolbar{display:flex;gap:12px;margin:18px 0}.toolbar input{flex:1}.toolbar input,.toolbar select,.toolbar button,input,select,textarea{border:1px solid #d6e1db;background:#fff;border-radius:9px;padding:10px 12px;font:inherit}.card{background:#fff;border:1px solid #dce5df;border-radius:14px;overflow:hidden}.empty{padding:60px;text-align:center;color:#7c8c84}table{width:100%;border-collapse:collapse}th,td{padding:14px 16px;border-bottom:1px solid #e9efec;text-align:left}th{font-size:11px;text-transform:uppercase;color:#819088;background:#f8faf9}td small{display:block;color:#84928b;margin-top:4px}.verified.yes{color:#12814b}.method{font-weight:800;color:#2773a0}.danger{color:#b32f2f}.back{margin-bottom:14px;padding:9px 12px;border:1px solid #d6e1db;background:#fff;border-radius:8px}.editor-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px}.editor-grid main,.editor-grid aside{display:grid;gap:16px;align-content:start}.form-card{padding:18px}.form-card label{display:grid;gap:6px;font-size:12px;font-weight:700;margin-top:12px}.details{display:grid;grid-template-columns:1fr 130px;gap:10px}.details .url{grid-column:1/-1}.pairs{padding:12px 0;border-bottom:1px solid #edf1ef}.pair{display:grid;grid-template-columns:1fr 2fr 38px;gap:8px;margin-top:8px}.value-with-variable{display:flex;gap:6px}.value-with-variable input{flex:1}.body{margin-top:16px}.body textarea{min-height:140px}.test-context{margin:16px 0;padding:14px;border:1px solid #cfe5db;background:#f5fbf8;border-radius:10px}.test-context label{margin:0}.context-note{display:grid;gap:3px;margin-top:10px;color:#60766d;font-size:12px}.context-note strong{color:#087443}.response{margin-top:14px;padding:14px;background:#f6f8f7;border-radius:9px;overflow:auto}.response.ok{background:#eefaf3}.response.bad,.error{background:#fff1f1;color:#a32929;padding:10px;border-radius:8px}.response-meta{display:flex;gap:16px;font-size:12px;margin-bottom:8px}.response pre{white-space:pre-wrap}.mapping-actions,.field-target{display:flex;gap:6px}.mapping-row{display:grid;grid-template-columns:1fr 20px 1fr 32px;gap:6px;align-items:end;margin-top:10px}.mapping-note,.root-map{margin:12px 0;padding:10px;background:#f3f8f5;border-radius:8px}.root-map{display:flex;justify-content:space-between;align-items:center}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto}.field-modal-bg{position:fixed;inset:0;background:#0006;display:grid;place-items:center;z-index:100}.field-modal{width:min(460px,90vw);background:#fff;border-radius:14px;padding:22px;display:grid;gap:10px}.field-modal footer{display:flex;justify-content:flex-end;gap:8px;margin-top:10px}@media(max-width:1000px){.http-page{margin-left:0;padding:20px}.editor-grid{grid-template-columns:1fr}}
</style>
